// Audio barge-in MVP runner.
//
// For each case in cases.json:
//   1. Launch headless Chromium with fake-mic flag pointed at the case's WAV
//      (pre-generated by generate-wavs.mjs).
//   2. Navigate to --base-url (default localhost:3000), auto-click the Start
//      Conversation button (matches `button[aria-label*="conversation"]`).
//   3. Observe for cases.observation_window_s (default 50s). Capture every
//      browser console message; extract user.transcription / assistant.transcription /
//      agent-state-changed events.
//   4. Apply the case's `expected` block as deterministic assertions; produce
//      per-check PASS/FAIL.
//   5. Aggregate into a graded JSON (same shape as scripts/qa-bench/grade.ts
//      output: { cases: [{ case_id, label, pass, checks: [{kind, criterion, pass, reason}] }] }).
//
// What's deliberately NOT here yet (post-MVP):
//   - Auto-start dev server (assumes user has one running)
//   - Parallel case execution (cases run sequentially; ~30s × N cases)
//   - Trial repetition for variance (--trials 1 only)
//   - Network/state-change latency metrics (just pass/fail for MVP)
//
// Usage:
//   node scripts/qa-bench/audio-barge-in/run.mjs \
//     [--base-url http://localhost:3000] \
//     [--cases scripts/qa-bench/audio-barge-in/cases.json] \
//     [--wav-dir /tmp/spike-mic/barge-in] \
//     [--out /tmp/spike-mic/barge-in/graded.json] \
//     [--only B01,B02]

import { chromium } from 'playwright';
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const args = process.argv.slice(2);
const get = (k, d) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : d; };
const BASE_URL = get('--base-url', 'http://localhost:3000');
const CASES_PATH = get('--cases', join(__dirname, 'cases.json'));
const WAV_DIR = get('--wav-dir', '/tmp/spike-mic/barge-in');
const OUT = get('--out', '/tmp/spike-mic/barge-in/graded.json');
const ONLY = get('--only')?.split(',').map((s) => s.trim()).filter(Boolean);

const cfg = JSON.parse(readFileSync(CASES_PATH, 'utf8'));
const OBSERVE_S = cfg.observation_window_s ?? 50;

const selected = ONLY ? cfg.cases.filter((c) => ONLY.includes(c.id)) : cfg.cases;
if (selected.length === 0) {
  console.error('no cases selected');
  process.exit(2);
}

// Pre-flight: dev server up?
try {
  const r = await fetch(BASE_URL, { signal: AbortSignal.timeout(3000) });
  if (r.status >= 500) throw new Error(`dev server returned ${r.status}`);
} catch (e) {
  console.error(`✗ dev server not reachable at ${BASE_URL}: ${e.message}`);
  console.error(`  start it with: pnpm dev   (in agora-voice-demo)`);
  process.exit(3);
}

mkdirSync(dirname(OUT), { recursive: true });

console.log(`base_url=${BASE_URL}`);
console.log(`cases=${selected.length} observe_window=${OBSERVE_S}s`);
console.log();

// Per-case structured event extraction. Parses console messages for the
// shape that AgoraVoiceAI emits via debug-log → '>>> [traceID:X] message {...}'
// and '>>> agent-state-changed UID {state, turnID, timestamp}'.
function extractEvents(consoleMessages) {
  const events = {
    user_transcriptions: [],     // {text, final, language, t_ms}
    assistant_transcriptions: [],
    agent_states: [],            // {state, turnID, timestamp}
  };
  for (const m of consoleMessages) {
    const txt = m.text;
    // 'message {...}' shape with transcription object
    if (txt.includes('"object":"user.transcription"')) {
      const tMatch = txt.match(/"text":"([^"]*)"/);
      const fMatch = txt.match(/"final":(true|false)/);
      const lMatch = txt.match(/"language":"([^"]*)"/);
      events.user_transcriptions.push({
        text: tMatch?.[1] ?? '',
        final: fMatch?.[1] === 'true',
        language: lMatch?.[1] ?? '',
        t_ms: m.t,
      });
    }
    if (txt.includes('"object":"assistant.transcription"')) {
      const tMatch = txt.match(/"text":"([^"]*)"/);
      const turnMatch = txt.match(/"turn_id":(\d+)/);
      // The agent's first turn is its greeting (always plays on session start).
      // User-triggered replies are turn_id >= 2. Distinguish them so `agent_replied`
      // can mean "post-greeting reply", which is what we actually care about.
      const isGreeting = txt.includes('"source":"greeting"') || txt.includes('"start_type":"greeting"');
      events.assistant_transcriptions.push({
        text: tMatch?.[1] ?? '',
        turn_id: Number(turnMatch?.[1] ?? -1),
        is_greeting: isGreeting,
        t_ms: m.t,
      });
    }
    if (txt.includes('agent-state-changed')) {
      const sMatch = txt.match(/"state":"(\w+)"/);
      const turnMatch = txt.match(/"turnID":(\d+)/);
      if (sMatch) {
        events.agent_states.push({ state: sMatch[1], turnID: Number(turnMatch?.[1] ?? -1) });
      }
    }
  }
  return events;
}

function runChecks(c, events) {
  const checks = [];
  const exp = c.expected;
  const finalSttTexts = events.user_transcriptions.filter((u) => u.final).map((u) => u.text);
  const allSttTexts = events.user_transcriptions.map((u) => u.text);
  const reachedStates = new Set(events.agent_states.map((s) => s.state));
  // "Reply" = post-greeting agent turn. The greeting (turn 1) is unconditional
  // on session start and is NOT a barge-in event. The signal is whether the
  // agent generated a turn AFTER the user audio (turn 2+).
  const postGreetingReplies = events.assistant_transcriptions.filter((a) => !a.is_greeting && a.turn_id >= 2);
  const replyTexts = postGreetingReplies.map((a) => a.text);
  const sawAnyReply = replyTexts.some((t) => t.trim().length > 0);

  // 1. stt_received_final
  if (typeof exp.stt_received_final === 'boolean') {
    const got = finalSttTexts.length > 0;
    checks.push({
      kind: 'deterministic',
      criterion: `stt_received_final == ${exp.stt_received_final}`,
      pass: got === exp.stt_received_final,
      reason: `got ${got} (n_final_transcripts=${finalSttTexts.length})`,
    });
  }

  // 2. stt_text_includes_any_of
  if (Array.isArray(exp.stt_text_includes_any_of)) {
    const concat = allSttTexts.join(' ').toLowerCase();
    const hit = exp.stt_text_includes_any_of.find((w) => concat.includes(w.toLowerCase()));
    checks.push({
      kind: 'deterministic',
      criterion: `stt text includes any of [${exp.stt_text_includes_any_of.join(', ')}]`,
      pass: !!hit,
      reason: hit ? `matched "${hit}"` : `none matched in "${concat.slice(0, 80)}"`,
    });
  }

  // 3. agent_state_transitioned_to (subset)
  if (Array.isArray(exp.agent_state_transitioned_to)) {
    if (exp.agent_state_transitioned_to.length === 0) {
      // Negative assertion — no non-trivial state changes for the user turn.
      // The greeting will always show 'speaking'; we tolerate states present
      // ONLY in the first 8s (greeting window).
      const lateStates = events.agent_states.filter((s) => s.turnID >= 2);
      checks.push({
        kind: 'deterministic',
        criterion: `agent state did NOT transition due to user turn`,
        pass: lateStates.length === 0,
        reason: lateStates.length === 0
          ? 'no states with turnID>=2'
          : `late state(s): ${lateStates.map((s) => `${s.state}@turn${s.turnID}`).join(', ')}`,
      });
    } else {
      const missing = exp.agent_state_transitioned_to.filter((s) => !reachedStates.has(s));
      checks.push({
        kind: 'deterministic',
        criterion: `agent reached states [${exp.agent_state_transitioned_to.join(', ')}]`,
        pass: missing.length === 0,
        reason: missing.length === 0
          ? `reached ${[...reachedStates].join(', ')}`
          : `missing ${missing.join(', ')}; reached ${[...reachedStates].join(', ')}`,
      });
    }
  }

  // 4. agent_replied
  if (typeof exp.agent_replied === 'boolean') {
    checks.push({
      kind: 'deterministic',
      criterion: `agent_replied == ${exp.agent_replied}`,
      pass: sawAnyReply === exp.agent_replied,
      reason: sawAnyReply ? `replied with: "${replyTexts[replyTexts.length - 1]?.slice(0, 60)}"` : 'no reply observed',
    });
  }

  // 5. agent_reply_excludes — forbidden substrings in any reply
  if (Array.isArray(exp.agent_reply_excludes)) {
    const concat = replyTexts.join(' ').toLowerCase();
    const hit = exp.agent_reply_excludes.find((w) => concat.includes(w.toLowerCase()));
    checks.push({
      kind: 'deterministic',
      criterion: `agent reply excludes [${exp.agent_reply_excludes.join(', ')}]`,
      pass: !hit,
      reason: hit ? `LEAKED "${hit}"` : 'absent',
    });
  }

  return checks;
}

async function runOneCase(c) {
  const wav = join(WAV_DIR, `${c.id}.wav`);
  if (!existsSync(wav)) {
    return {
      case_id: c.id, label: c.label, pass: false, error: `WAV missing: ${wav}`,
      checks: [], events: null,
    };
  }
  const browser = await chromium.launch({
    headless: true,
    args: [
      '--use-fake-device-for-media-stream',
      '--use-fake-ui-for-media-stream',
      `--use-file-for-fake-audio-capture=${wav}`,
      '--autoplay-policy=no-user-gesture-required',
    ],
  });
  const ctx = await browser.newContext({ permissions: ['microphone'], viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  const startT = Date.now();
  const consoleMessages = [];
  page.on('console', (m) => {
    consoleMessages.push({ t: Date.now() - startT, type: m.type(), text: m.text() });
  });
  page.on('pageerror', (e) => {
    consoleMessages.push({ t: Date.now() - startT, type: 'pageerror', text: e.message });
  });
  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded', timeout: 30000 });
  await page.waitForTimeout(1500);
  // Click start.
  const btn = page.locator('button[aria-label*="conversation" i], button:has-text("Start Conversation")').first();
  if (await btn.count() === 0) {
    await browser.close();
    return { case_id: c.id, label: c.label, pass: false, error: 'start button not found', checks: [], events: null };
  }
  try { await btn.click({ timeout: 5000 }); } catch (e) {
    await browser.close();
    return { case_id: c.id, label: c.label, pass: false, error: `start click failed: ${e.message}`, checks: [], events: null };
  }
  // Observe.
  await page.waitForTimeout(OBSERVE_S * 1000);
  await browser.close();

  const events = extractEvents(consoleMessages);
  const checks = runChecks(c, events);
  const pass = checks.every((x) => x.pass);
  return { case_id: c.id, label: c.label, axis: c.axis, pass, checks, events };
}

console.log('| case | label | verdict | failed checks |');
console.log('|---|---|---|---|');
const results = [];
for (const c of selected) {
  process.stdout.write(`  running ${c.id} (${c.label}) ...`);
  const r = await runOneCase(c);
  results.push(r);
  const failed = r.checks?.filter((x) => !x.pass).map((x) => x.criterion).join('; ') || (r.error ?? '—');
  console.log(`\r| ${r.case_id} | ${r.label} | ${r.pass ? '✅ PASS' : '❌ FAIL'} | ${failed} |`);
}

const nPass = results.filter((r) => r.pass).length;
const summary = {
  generated_at: new Date().toISOString(),
  base_url: BASE_URL,
  observe_window_s: OBSERVE_S,
  n_cases: results.length,
  n_pass: nPass,
  n_fail: results.length - nPass,
  cases: results,
};
writeFileSync(OUT, JSON.stringify(summary, null, 2));
console.log(`\n${nPass}/${results.length} PASS — wrote ${OUT}`);

// FBR (False Barge-in Rate) — % of false-positive-* axis cases that
// triggered an agent state transition or reply. Headline KPI for this
// sub-bench.
const fpCases = results.filter((r) => r.axis?.startsWith('false-positive'));
if (fpCases.length > 0) {
  const fpTriggered = fpCases.filter((r) => {
    if (!r.events) return false;
    const lateStates = r.events.agent_states.filter((s) => s.turnID >= 2);
    return lateStates.length > 0 || r.events.user_transcriptions.some((u) => u.final);
  });
  const fbr = fpTriggered.length / fpCases.length;
  console.log(`FBR (false barge-in rate) = ${(fbr * 100).toFixed(1)}% — ${fpTriggered.length}/${fpCases.length} non-speech cases triggered a turn`);
}

if (nPass !== results.length) process.exitCode = 1;
